// Change these. The SMS gateway (Twilio here) sends each incoming text.
const b = $input.first().json.body || {};
return [{
  json: {
    // Where the OPD Saathi server runs (must be reachable from n8n).
    apiBase: 'http://localhost:5050',
    // The same value as SMS_KEY in the OPD Saathi server's .env file.
    smsKey: 'PUT-THE-SMS_KEY-HERE',
    // Twilio sends From and Body; other gateways use other names.
    from: b.From || b.from || b.sender || '',
    text: b.Body || b.text || b.message || '',
  },
}];

// Twilio reads its reply from TwiML (XML). Escape the text for XML.
const reply = String($json.reply || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
return [{ json: { twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Message>${reply}</Message></Response>` } }];
